import { createRequire } from "node:module";

import { orsoGlob } from "../../integrations/orso/index.js";

const require = createRequire(import.meta.url);
const getZod = () => require("astro/zod").z;

/*
 * The site's content models: one Astro collection per folder under `src/content/`, each loaded
 * with `orsoGlob` so Orso can edit its entries. This file belongs to the site; edit it to add a
 * collection or change a field. `astro.config.mjs` passes `collections` to
 * `orso({ collections })`, and `src/content.config.ts` re-exports them from
 * `virtual:orso/collections`.
 */

/** @param {{ loader: unknown, schema: unknown }} config */
function contentCollection(config) {
  return { ...config, type: "content_layer" };
}

/** Sample posts for the starter — delete or replace when you define your own models. */
const posts = contentCollection({
  loader: orsoGlob({ base: "./src/content/posts", pattern: "*.md" }),
  schema: () => {
    const z = getZod();
    return z.object({
      title: z.string(),
      date: z
        .string()
        .regex(/^\d{4}-\d{2}-\d{2}$/, "Use YYYY-MM-DD")
        .refine(
          (value) => {
            const date = new Date(`${value}T00:00:00Z`);
            return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === value;
          },
          "Use a valid calendar date",
        )
        .meta({ editor: { type: "date", knownRefinement: true } }),
    });
  },
});

/**
 * `orso({ collections })` entries, in sidebar order. `previewPath` is the page an entry is shown
 * on (`slug` is the entry id, the Markdown filename without extension).
 */
export const collections = {
  posts: { collection: posts, previewPath: ({ slug }) => `/posts/${slug}/` },
};

import assert from "node:assert/strict";
import { test } from "node:test";
import { spawnSync } from "node:child_process";
import { cpSync, existsSync, mkdtempSync, readFileSync, rmSync, symlinkSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");

test("astro sync writes the orso content manifest", () => {
  const dir = mkdtempSync(join(tmpdir(), "orso-manifest-"));
  try {
    for (const path of ["src", "public", "integrations", "astro.config.mjs", "package.json"]) {
      cpSync(join(root, path), join(dir, path), { recursive: true });
    }
    symlinkSync(join(root, "node_modules"), join(dir, "node_modules"), "dir");
    const result = spawnSync(process.execPath, [join(root, "node_modules/astro/bin/astro.mjs"), "sync"], {
      cwd: dir,
      encoding: "utf8",
      env: process.env,
    });
    assert.equal(result.status, 0, result.stdout + result.stderr);

    const path = join(dir, ".astro/orso-content.json");
    assert.ok(existsSync(path), `missing ${path}\n${result.stdout}${result.stderr}`);
    const manifest = JSON.parse(readFileSync(path, "utf8"));
    assert.equal(manifest.version, 1);
    assert.deepEqual(
      manifest.collections.map(({ name }) => name),
      ["posts"],
    );
    const byName = Object.fromEntries(manifest.collections.map((collection) => [collection.name, collection]));
    assert.deepEqual(byName.posts.loader, { base: "src/content/posts", pattern: "*.md" });
    for (const collection of manifest.collections) {
      assert.equal(collection.supportedForEditing, true, collection.reason);
    }
    assert.equal(byName.posts.fields.properties.date.type, "date");
    assert.equal(byName.posts.fields.properties.title.type, "string");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

import { getCollection, type CollectionEntry } from "astro:content";

export type Post = CollectionEntry<"posts">;

/** All posts, newest `date` first. */
export async function loadPosts(): Promise<Post[]> {
  const posts = await getCollection("posts");
  return posts.sort((a, b) => b.data.date.localeCompare(a.data.date));
}

/** Format a YYYY-MM-DD date for display. */
export function formatDate(value: string): string {
  const date = new Date(`${value}T00:00:00Z`);
  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
}

import { loadPosts } from "./posts";

export interface SitePage {
  /** Site path, e.g. `/posts/hello-orso/`. */
  path: string;
  /** Last change (YYYY-MM-DD), when known. */
  lastmod?: string;
}

/**
 * Paths of the static `.astro` pages in src/pages (no `[param]` routes, no `_` files, no 404),
 * so a page you add shows up in the sitemap without editing this file.
 */
const staticPaths = () =>
  Object.keys(import.meta.glob("../pages/**/*.astro"))
    .map((file) => file.replace(/^\.\.\/pages/, "").replace(/\.astro$/, ""))
    .filter((route) => !/\[|\/_|^\/404$/.test(route))
    .map((route) => route.replace(/\/index$/, "/").replace(/([^/])$/, "$1/"));

/** Every page of the built site: static pages and sample posts. */
export async function sitePages(): Promise<SitePage[]> {
  const posts = await loadPosts();
  const pages: SitePage[] = [
    ...staticPaths().map((path) => ({ path })),
    ...posts.map((post) => ({ path: `/posts/${post.id}/`, lastmod: post.data.date })),
  ];
  const seen = new Set<string>();
  return pages
    .filter((page) => !seen.has(page.path) && seen.add(page.path))
    .sort((a, b) => (a.path === "/" ? -1 : b.path === "/" ? 1 : a.path.localeCompare(b.path)));
}

